package edu.alliance.medislot.servlet;import edu.alliance.medislot.dao.*;import edu.alliance.medislot.service.*;import edu.alliance.medislot.exception.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;@WebServlet("/api/auth/*")public class AuthServlet extends JsonServlet{private final AuthService auth=new AuthService();protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String a=q.getPathInfo();if("/logout".equals(a)){HttpSession s=q.getSession(false);if(s!=null)s.invalidate();send(r,200,Map.of("message","Signed out."));return;}var b=body(q);UserDao.Account u;if("/login".equals(a)){u=auth.login(val(b,"email"),val(b,"password"));if(u==null){error(r,401,"Email or password is incorrect.");return;}HttpSession old=q.getSession(false);if(old!=null)old.invalidate();}else if("/register".equals(a)){u=auth.register(val(b,"name"),val(b,"email"),val(b,"password"),val(b,"phone"));}else{error(r,404,"Unknown auth action.");return;}HttpSession s=q.getSession(true);s.setAttribute("userId",u.id());s.setAttribute("role",u.role());s.setAttribute("name",u.name());send(r,"/register".equals(a)?201:200,view(u));}catch(ValidationException e){error(r,400,e.getMessage());}catch(ConflictException e){error(r,409,e.getMessage());}catch(Exception e){getServletContext().log("Auth error",e);error(r,500,"Request could not be completed.");}}protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{if(!"/me".equals(q.getPathInfo())){error(r,404,"Unknown auth action.");return;}try{UserDao.Account u=new UserDao().byId((Long)q.getSession(false).getAttribute("userId"));if(u==null)error(r,401,"Session expired.");else send(r,200,view(u));}catch(Exception e){error(r,500,"Unable to load account.");}}private String val(com.fasterxml.jackson.databind.JsonNode n,String k){return n.hasNonNull(k)?n.get(k).asText():null;}private Map<String,Object> view(UserDao.Account u){return Map.of("id",u.id(),"name",u.name(),"email",u.email(),"role",u.role());}}